if(typeof auth!="undefined"){const e=db.collection("views"),t=db.collection("likes");function numberWithCommas(e){return e.toString().replace(/\B(?=(\d{3})+(?!\d))/g,",")}const n=function(t,n){e.doc(n).onSnapshot(e=>{const n=e.data();t.innerText=n?numberWithCommas(n.views):"0",t.classList.remove("counter-loading")})},s=function(e,n){t.doc(n).onSnapshot(t=>{const n=t.data();e.innerText=n?numberWithCommas(n.likes):"0",e.classList.remove("counter-loading")})};auth.signInAnonymously().then(()=>{const e=document.querySelectorAll("span[id^='views_']");e.forEach(e=>{const t=e.id?.replaceAll("/","-");t&&n(e,t)});const t=document.querySelectorAll("span[id^='likes_']");t.forEach(e=>{const t=e.id?.replaceAll("/","-");t&&s(e,t)})}).catch(e=>console.error(e.code,e.message))}